namespace BlackMarket.Editor {
 public static class UndergroundBuilder {
  const string Root="Assets/BlackMarket/";static GameObject world;static Material concrete,metal,floor,orange,screen,white;static int props;
  [MenuItem("BLACK MARKET/Build underground campaign")]
  public static void BuildControlOnly(){controlOnly=true;Build();controlOnly=false;}
  static bool controlOnly;
  public static void Build(){
   Directory.CreateDirectory(Root+"Art/Underground/Materials");AssetDatabase.Refresh();
   concrete=Mat("Concrete",new Color(.22f,.25f,.25f));metal=Mat("Steel",new Color(.09f,.13f,.14f));floor=Mat("Floor",new Color(.45f,.48f,.48f));var sourceFloor=AssetDatabase.LoadAssetAtPath<Material>(Root+"Resources/Materials/concrete_floor_02.mat");if(sourceFloor){floor.CopyPropertiesFromMaterial(sourceFloor);floor.mainTextureScale=new Vector2(12,16);}orange=Mat("Warning",new Color(.85f,.43f,.08f));screen=Mat("Screen",new Color(.02f,.25f,.32f),true);white=Mat("Light",new Color(.65f,.8f,.85f),true);
   foreach(var name in new[]{"ammo_box","industrial_storage_cart","industrial_caged_sconce"})ImportMaterial(name);
   if(!controlOnly)BuildWorld(false);BuildWorld(true);PatchArmoryGear();if(!controlOnly)PatchUsb();AssetDatabase.SaveAssets();EditorSceneManager.OpenScene(Root+"Scenes/NorthPoint.unity");Debug.Log("UNDERGROUND BUILD COMPLETE / "+props+" props");
  }
  static Material Mat(string name,Color color,bool emission=false){string path=Root+"Art/Underground/Materials/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.color=color;m.SetFloat("_Smoothness",.28f);if(emission){m.EnableKeyword("_EMISSION");m.SetColor("_EmissionColor",color*2);}return m;}
  static void ImportMaterial(string name){string dir=Root+"Art/Underground/Sources/"+name;var m=Mat(name,Color.white);foreach(var path in Directory.GetFiles(dir,"*.png")){var ti=AssetImporter.GetAtPath(path) as TextureImporter;if(ti){ti.maxTextureSize=1024;if(path.Contains("nor_gl"))ti.textureType=TextureImporterType.NormalMap;ti.SaveAndReimport();}var t=AssetDatabase.LoadAssetAtPath<Texture2D>(path);if(path.ToLower().Contains("diff"))m.SetTexture("_BaseMap",t);if(path.Contains("metallic_smoothness")){if(ti){ti.sRGBTexture=false;ti.SaveAndReimport();}m.SetTexture("_MetallicGlossMap",t);m.SetFloat("_Smoothness",1);m.EnableKeyword("_METALLICSPECGLOSSMAP");}if(path.Contains("nor_gl")){m.SetTexture("_BumpMap",t);m.EnableKeyword("_NORMALMAP");}}}
  static GameObject Box(string name,Vector3 p,Vector3 scale,Material mat,bool collider=true){var o=GameObject.CreatePrimitive(PrimitiveType.Cube);o.name=name;o.transform.SetParent(world.transform);o.transform.position=p;o.transform.localScale=scale;o.GetComponent<Renderer>().sharedMaterial=mat;if(!collider)Object.DestroyImmediate(o.GetComponent<Collider>());return o;}
  static void Marker(string id,Vector3 p){var o=new GameObject(id);o.transform.SetParent(world.transform);o.transform.position=p;o.AddComponent<WorldMarker>().id=id;}
  static void Sign(string text,Vector3 p,float width=1){var o=new GameObject(text);o.transform.SetParent(world.transform);o.transform.position=p;o.transform.rotation=Quaternion.identity;var t=o.AddComponent<TextMesh>();t.text=text;t.font=Resources.Load<Font>("Fonts/Bold");t.fontSize=64;t.characterSize=.055f*width;t.anchor=TextAnchor.MiddleCenter;t.color=new Color(.7f,.88f,.88f);o.GetComponent<Renderer>().sharedMaterial=t.font.material;o.AddComponent<WorldTextDepth>();if(text.StartsWith("006"))o.transform.rotation=Quaternion.Euler(0,180,0);if(text.StartsWith("NGUỒN"))o.transform.rotation=Quaternion.Euler(0,-90,0);}
  static void Point(string id,string title,Vector3 p){var o=new GameObject(title);o.transform.SetParent(world.transform);o.transform.position=p;var i=o.AddComponent<Interaction>();i.id=id;i.title=title;}
  static GameObject Prop(string path,Vector3 p,float width,float angle=0,Material overrideMat=null){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(!prefab){Debug.LogError("Missing prop "+path);return null;}var o=Object.Instantiate(prefab,world.transform);o.transform.position=Vector3.zero;if(!path.Contains("Underground/Sources/"))o.transform.rotation=Quaternion.identity;foreach(var i in o.GetComponentsInChildren<Interaction>())Object.DestroyImmediate(i);foreach(var c in o.GetComponentsInChildren<Collider>())Object.DestroyImmediate(c);var rs=o.GetComponentsInChildren<Renderer>();if(rs.Length==0)return o;var bounds=rs[0].bounds;foreach(var r in rs)bounds.Encapsulate(r.bounds);float scale=width/Mathf.Max((path.Contains("Resources/Actors/")||path.Contains("Underground/Sources/"))?Mathf.Max(bounds.size.x,bounds.size.y,bounds.size.z):bounds.size.x,.001f);o.transform.localScale*=scale;var center=bounds.center*scale;var bottom=bounds.min.y*scale;foreach(var r in rs)if(overrideMat)r.sharedMaterials=r.sharedMaterials.Select(x=>overrideMat).ToArray();o.transform.position=new Vector3(-center.x,-bottom,-center.z);var holder=new GameObject(prefab.name);holder.transform.SetParent(world.transform);o.transform.SetParent(holder.transform,true);holder.transform.SetPositionAndRotation(p,Quaternion.Euler(0,angle,0));props++;return holder;}
  static GameObject Shop(string name,Vector3 p,float width,float angle=0)=>Prop(Root+"Prefabs/Shop/"+name+".prefab",p,width,angle);
  static void Scan(string name,Vector3 p,float width,float angle=0)=>Prop(Root+"Art/Underground/Sources/"+name+"/"+name+"_1k.fbx",p,width,angle,AssetDatabase.LoadAssetAtPath<Material>(Root+"Art/Underground/Materials/"+name+".mat"));
  static void Gate(string name,Vector3 p,Vector3 size){var o=Box(name,p,size,metal);o.AddComponent<NavMeshModifier>().ignoreFromBuild=true;var obstacle=o.AddComponent<UnityEngine.AI.NavMeshObstacle>();obstacle.shape=UnityEngine.AI.NavMeshObstacleShape.Box;obstacle.size=Vector3.one;obstacle.carving=true;}
  static void Desk(float x,float z,bool central=false){var block=Box("Bàn / vật che",new Vector3(x,.55f,z),new Vector3(3.2f,1.1f,1.2f),metal);Shop("Desktop computer",new Vector3(x,1.12f,z),1.1f,180);Shop("Chair - ghe nhua",new Vector3(x,0,z+1.35f),.65f,180);Marker("cover_"+x+"_"+z,new Vector3(x,0,z+1.7f));}
