    float a=(-34+col*68f/6)*Mathf.Deg2Rad,r=14+row*10;var p=new Vector3(Mathf.Sin(a)*r,0,50-Mathf.Cos(a)*r);float yaw=-a*Mathf.Rad2Deg;
    var desk=Box("Bàn điều phối vòng cung",p+Vector3.up*.55f,new Vector3(2.7f,1.1f,1.2f),metal);desk.transform.rotation=Quaternion.Euler(0,yaw,0);
    Shop("Desktop computer",p+Vector3.up*1.12f,1.05f,yaw+180);Shop("Office swivel chair",p-Quaternion.Euler(0,yaw,0)*Vector3.forward*1.1f,.65f,yaw);
    Marker("cover_arc_"+row+"_"+col,p-Quaternion.Euler(0,yaw,0)*Vector3.forward*1.6f);
   }
   if(control)foreach(float x in new[]{-19f,19f})foreach(float z in new[]{7f,12f,39f,44f,48f}){Shop("Stockroom steel rack - ke kho",new Vector3(x,0,z),3,90);Box("Kệ thùng hồ sơ",new Vector3(x,.85f,z),new Vector3(1.2f,1.7f,3),metal);for(int n=0;n<6;n++)Box("Thùng tài liệu niêm phong",new Vector3(x,1.9f+(n/3)*.45f,z-.9f+(n%3)*.9f),new Vector3(.8f,.4f,.7f),concrete,false);Marker("cover_archive_"+x+"_"+z,new Vector3(x>0?x-1.4f:x+1.4f,0,z));}
   for(float z=17;z<depth-7;z+=8)foreach(float x in new[]{-19f,19f}){Shop("Stockroom steel rack - ke kho",new Vector3(x,0,z),3.2f,90);var rackBlock=Box("Kệ / vật che",new Vector3(x,.85f,z),new Vector3(1.1f,1.7f,3.2f),metal);rackBlock.GetComponent<Renderer>().enabled=false;if(!control)Prop(Root+"Resources/Actors/AK.prefab",new Vector3(x,1.8f,z),.95f,90);else for(int k=0;k<6;k++)Box("Classeurs / dossiers",new Vector3(x,1.8f,z-1+k*.35f),new Vector3(.65f,.35f,.24f),k%2==0?concrete:orange,false);for(int j=0;j<3;j++)Scan("ammo_box",new Vector3(x,.95f,z-1+j),.65f,90);if(control){Box("Tủ máy chủ",new Vector3(x,1.3f,z+3),new Vector3(1.1f,2.6f,1),metal);for(int y=0;y<6;y++)Box("Trạng thái máy chủ",new Vector3(x-.56f,.5f+y*.32f,z+3),new Vector3(.02f,.05f,.6f),screen,false);}}
   for(int i=0;i<4;i++)Scan("industrial_storage_cart",new Vector3(i%2==0?-17:17,0,24+i*6),1.2f,90);
   for(float z=12;z<depth;z+=16){Scan("industrial_caged_sconce",new Vector3(-21.6f,2.6f,z),.4f,90);var o=new GameObject("Emergency / đèn dự phòng");o.transform.SetParent(world.transform);o.transform.position=new Vector3(0,4,z);var l=o.AddComponent<Light>();l.range=13;l.intensity=.12f;l.color=new Color(.2f,.5f,.35f);}
   for(int i=0;i<12;i++){Box("Repère au sol",new Vector3(-2,.015f,8+i*3.7f),new Vector3(.08f,.015f,1.6f),orange,false);Box("Repère au sol",new Vector3(2,.015f,8+i*3.7f),new Vector3(.08f,.015f,1.6f),orange,false);}
   Marker("spawn",new Vector3(0,.1f,6));Marker("breach",new Vector3(0,0,control?-5:2));Marker("combat_focus",new Vector3(0,0,30));for(int i=0;i<4;i++)Marker("enemy_"+i,new Vector3(control?(-1.5f+i):(-4+i*2.7f),control?2:.1f,control?-5:4));
   Gate("Breach intact",new Vector3(0,1.8f,control?-6:1),new Vector3(5,3.6f,.3f));var wreck=Box("Breach wreck",new Vector3(3,.25f,control?-5:2),new Vector3(2,.35f,1.2f),metal,false);wreck.transform.rotation=Quaternion.Euler(0,25,12);wreck.SetActive(false);
   if(!control){
    Sign("B1 / QUÂN GIỚI — KHU VỰC HẠN CHẾ",new Vector3(0,4,63));
    foreach(float x in new[]{-12f,-6,0}){Box("Bàn quân giới",new Vector3(x,.65f,12),new Vector3(4,1.3f,1.5f),metal);}
    Prop(Root+"Resources/Actors/Pistol.prefab",new Vector3(-12,1.32f,12),.65f);Point("pistol","LẤY SÚNG LỤC",new Vector3(-12,1.2f,11));Prop(Root+"Resources/Actors/AK.prefab",new Vector3(-6,1.32f,12),1.1f);Point("ak","LẤY AK",new Vector3(-6,1.2f,11));Scan("ammo_box",new Vector3(0,1.32f,12),.85f);Point("grenades","LẤY LỰU ĐẠN / ĐẠN",new Vector3(0,1.2f,11));
    Desk(17,21);Point("base_computer","MÁY TÍNH VẬN HÀNH / USB",new Vector3(17,1,22.1f));Sign("MÁY TÍNH VẬN HÀNH",new Vector3(17,2.6f,22));
    Point("retreat","XUỐNG TRUNG TÂM ĐIỀU PHỐI",new Vector3(0,1,60));Gate("Retreat gate",new Vector3(0,1.8f,63),new Vector3(4,3.6f,.3f));Box("Hành lang rút lui",new Vector3(0,-.3f,67),new Vector3(4,.6f,8),floor);for(int i=0;i<12;i++)Box("Bậc thang",new Vector3(0,-i*.2f-.2f,65+i*.4f),new Vector3(4,.4f,.42f),concrete);Marker("retreat_end",new Vector3(0,-2.2f,69));Box("Bóng tối cầu thang",new Vector3(0,-.5f,70),new Vector3(4,4,.1f),metal,false);
   }else{
