    var display=Mat("ControlDisplay",Color.white);display.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"Art/Underground/control_display.png"));display.EnableKeyword("_EMISSION");display.SetTexture("_EmissionMap",display.mainTexture);display.SetColor("_EmissionColor",Color.white*.65f);display.SetTextureScale("_BaseMap",new Vector2(-1,-1));display.SetTextureOffset("_BaseMap",Vector2.one);Box("Màn hình điều phối trung tâm",new Vector3(0,3.3f,51.5f),new Vector3(18,4,.2f),display,false);Sign("NORTH POINT / ĐIỀU PHỐI\nMÁY CHỦ LƯU TRỮ ORDER 71",new Vector3(0,5.25f,51.3f),.7f);for(int i=0;i<7;i++)Box("Dữ liệu hiển thị",new Vector3(-7+i*2.3f,2.1f,51.3f),new Vector3(1.5f,.08f,.02f),white,false);
