   var nav=world.AddComponent<NavMeshSurface>();nav.collectObjects=CollectObjects.Children;nav.useGeometry=UnityEngine.AI.NavMeshCollectGeometry.PhysicsColliders;nav.BuildNavMesh();string navPath=Root+"Art/Underground/"+world.name+"Nav.asset";var old=AssetDatabase.LoadAssetAtPath<UnityEngine.AI.NavMeshData>(navPath);if(old){EditorUtility.CopySerialized(nav.navMeshData,old);nav.RemoveData();nav.navMeshData=old;nav.AddData();}else AssetDatabase.CreateAsset(nav.navMeshData,navPath);
