  static void PatchArmoryGear(){var path=Root+"Resources/Worlds/UndergroundArmory.prefab";var o=PrefabUtility.LoadPrefabContents(path);var item=o.GetComponentsInChildren<Interaction>(true).First(i=>i.id=="grenades");item.title="LẤY KÍNH NHÌN ĐÊM / LỰU ĐẠN / ĐẠN";if(!o.transform.Find("Kính nhìn đêm tại kho")){var goggles=Object.Instantiate(Resources.Load<GameObject>("Actors/NightVisionGoggles"),o.transform);goggles.name="Kính nhìn đêm tại kho";goggles.transform.localPosition=new Vector3(-9.5f,1.5f,16);goggles.transform.localRotation=Quaternion.Euler(0,180,0);}PrefabUtility.SaveAsPrefabAsset(o,path);PrefabUtility.UnloadPrefabContents(o);}
  static void PatchUsb(){string path=Root+"Resources/Worlds/NorthPointShop.prefab";var root=PrefabUtility.LoadPrefabContents(path);try{var item=root.GetComponentsInChildren<Interaction>(true).FirstOrDefault(i=>i.id=="keycard");if(item){item.title="USB ĐỎ / KHÓA BẢO MẬT CỦA MARCUS";foreach(Transform child in item.transform.Cast<Transform>().ToArray())if(child.name=="USB đỏ")Object.DestroyImmediate(child.gameObject);foreach(var r in item.GetComponentsInChildren<Renderer>())r.enabled=false;var usb=GameObject.CreatePrimitive(PrimitiveType.Cube);usb.name="USB đỏ";usb.transform.SetParent(item.transform,false);usb.transform.localScale=new Vector3(.12f/item.transform.lossyScale.x,.025f/item.transform.lossyScale.y,.055f/item.transform.lossyScale.z);usb.GetComponent<Renderer>().sharedMaterial=Mat("USB Red",new Color(.65f,.025f,.02f));Object.DestroyImmediate(usb.GetComponent<Collider>());var plug=GameObject.CreatePrimitive(PrimitiveType.Cube);plug.transform.SetParent(usb.transform,false);plug.transform.localPosition=new Vector3(.62f,0,0);plug.transform.localScale=new Vector3(.3f,.7f,.8f);plug.GetComponent<Renderer>().sharedMaterial=white;Object.DestroyImmediate(plug.GetComponent<Collider>());}PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}}
 }
